insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('110-4301-006','110-4301',6,'single_choice','甲、乙、丙、丁及戊五位自然人共同出資設立A 有限公司（下稱A 公司），並選任甲及乙為董事， 甲並擔任董事長。A 公司欲於新北市興建新廠房，甲所有之土地之落座地點正適合作為興建廠房之 用，因此A 公司欲向甲購買該筆土地，依主管機關見解，下列敘述何者正確？','經全體股東授權後，得由甲為A 公司之代表與其本人訂立買賣契約','甲有利益衝突，董事間又礙於情誼，不適合代表公司，故應由監察人代表A 公司與甲訂立買賣契約','由全體股東之同意另推選有行為能力之股東代表A 公司與甲訂立買賣契約','由乙代表A 公司與甲訂立買賣契約','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-4301-007','110-4301',7,'single_choice','A 股份有限公司（下稱A 公司）為公開發行股票之公司，主要業務為生產手機按鍵零件，但近年來 因為智慧型手機盛行，故該公司連年虧損。甲為A 公司之股東，在股東會中提出減資之臨時動議， 並獲決議通過。依據公司法規定，下列敘述何者正確？','該臨時動議違反股東會召集程序之規定，故該決議不成立','該臨時動議違反股東會召集程序之規定，故該決議得撤銷','該臨時動議違反股東會召集程序之規定，該決議無效','該臨時動議未違反股東會召集程序之規定','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-4301-008','110-4301',8,'single_choice','A 股份有限公司設有董事5 人，董事長甲於配偶死亡後，便無心公司事務。乙、丙及丁三位董事提議 解除甲之董事長職務，改由其他董事擔任，以書面請求甲召開董事會，甲拒絕召開，三位董事便自行 召集董事會，開會時，甲刻意出席欲以主席身分杯葛議事，雙方上演全武行。依法律規定及實務見 解，下列敘述何者正確？','該次董事會主席應由乙、丙及丁互相推選之','非董事長者，無權召集董事會，此次董事會違法','三位董事已達過半席次，可逕行召集董事會，無須先請求董事長召集','三位董事自行召集前，未先經主管機關許可，並不合法','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-4301-009','110-4301',9,'single_choice','A 股份有限公司（下稱A 公司）從未公開發行股票，其董事長甲因私自挪用公司資產，被法院判決 有罪、處有期徒刑3 年，甲因不服該判決而上訴，以致本案仍未確定。今甲從羈押中釋放出來，又再 回任A 公司董事長。股東乙持有A 公司已發行股份總數百分之三之股份已有半年，因不滿現狀，於 A 公司受理股東提案期間內，以書面向公司提出下列股東常會議案，案由為：「公司負責人首重誠實 信用，本公司現任董事長甲因私自挪用公司資產，業經法院判決有罪，繼續留任顯將嚴重影響本公司 正常營運及股東權利，爰擬解任其董事職務，請予同意，謹提請討論。」A 公司董事會應否將上述乙 之提案列入股東會議案？','應該，乙之提案符合法律規定','不應該，乙之持股期間未達1 年，不得提案','不應該，乙之提案未達300 字','不應該，乙之提案非股東會所得決議者','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-4301-010','110-4301',10,'single_choice','A 股份有限公司經營不善，股東們對於董事會效能非常不滿意，打算召集股東臨時會改選董監。其中 小股東甲為繼續1 年以上持股1%的股東，乙為繼續6 個月以上持股10%的股東，丙為繼續6 個月以 上持股25%的股東，丁為繼續3 個月以上持股30%的股東，戊為公司監察人。下列關於股東會之敘 述，何者正確？','甲、乙得共同以書面記明提議事項及理由，請求董事會召集股東臨時會。若董事會15 日內不為召 集，則甲、乙得自行召集','乙、丙得共同以書面記明提議事項及理由，報請主管機關許可後，乙、丙可召集股東臨時會','丙、丁毋庸請求董事會同意及主管機關許可，得共同隨時自行召集股東臨時會','戊若未持有股份，則不得自行召集股東臨時會','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-4301-011','110-4301',11,'single_choice','甲為A 公開發行股票之公司（下稱A 公司）之董事，選任時持股10,000 股，任期中再買進10,000 股，後將其持有20,000 股全部設定質權。依實務見解，A 公司股東會中甲最多得行使表決權之股份 數為何？','0 股','5,000 股','10,000 股','15,000 股','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-4301-012','110-4301',12,'single_choice','A 上市公司（下稱A 公司）本年度股東常會之主要議案有三：（一）改選董監事，（二）與B 公司 之合併案，（三）購買股東甲所有之土地一筆。A 公司之股東甲為本次董監改選之董事候選人，B 公 司持有A 公司5%之股權，下列敘述何者正確？','甲就議案（一）及議案（三）皆不得行使表決權，而B 公司就議案（二）不得行使表決權','甲就議案（一）及議案（三）皆不得行使表決權，而B 公司就議案（二）得行使表決權','甲僅就議案（三）不得行使表決權，而B 公司就議案（二）不得行使表決權','甲僅就議案（三）不得行使表決權，而B 公司就議案（二）得行使表決權','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-4301-013','110-4301',13,'single_choice','X 股份有限公司設有九席董事，分別由A、B、C、D、E、F、G、H、I 擔任，其中A、B、C 為常務 董事，A 為董事長，B 為副董事長。依公司法之規定，下列敘述何者錯誤？','A、B、C 三位常務董事，由股東會選任之','B 之副董事長職務，由常務董事會選任之','A 請假無法行使董事長職權時，由B 代理行使職權','常務董事會決議解任A 之董事長職務後，A 仍為公司董事','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-4301-014','110-4301',14,'single_choice','A 股份有限公司（下稱A 公司）為非公開發行股票之公司，章程記載資本總額為新臺幣（下同） 10 億元，已發行9.9 億元，為擴充廠房，需增資3 億元。下列敘述何者正確？','A 公司須將原章程記載之資本總額全數發行完畢後，始可變更章程','A 公司得先變更章程提高資本額，再發行新股','為求時效，A 公司可先增資3 億元後，再補辦變更章程之程序，於完成修章程序後，始發生增資之 效力','A 公司所需之3 億資金，必須一次募足，不得分次發行','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-4301-015','110-4301',15,'single_choice','A 股份有限公司（下稱A 公司）為B 股份有限公司（下稱B 公司）之控制公司，當B 公司欲任命任 何高階業務主管時，均事先徵得A 公司之同意。去年A 公司為其自身利益，間接使B 公司為不利益 之經營，但未於會計年度終了時為適當之補償，致B 公司受有損害，但A 公司未賠償B 公司之損 害。甲於2 年前借給B 公司新臺幣50 萬元，尚未獲得清償，屢屢函請B 公司儘速對A 公司採取法 律行動，未料B 公司卻逕自聲明不會為此向A 公司求償，下列敘述何者正確？','甲無代位求償權，因A 公司並未持有B 公司已發行有表決權股份總數半數以上','甲對B 公司之債權未超過新臺幣100 萬元，不能代位求償','因B 公司拋棄請求賠償權利，甲不能代位求償','甲得以自己名義行使B 公司權利，請求A 公司對B 公司為給付','公司法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-4301-016','110-4301',16,'single_choice','原保險契約與再保險契約皆另行於契約條款約定，原保險之被保險人得直接向再保險人請求保險金， 而再保險人也得向原保險之要保人請求保險費。若原保險契約之原保險人失去清償能力，原被保險 人得否直接向再保險人請求保險金？','可，原被保險人本來就是再保險契約保護之對象，該契約條款純屬多餘','可，原保險契約與再保險契約雖各自獨立，但由於契約條款已另行約定，故原被保險人例外得直接 向再保險人請求保險金','否，原保險契約與再保險契約係各自獨立，該契約條款牴觸保險法第54 條第1 項之規定而無效','否，該契約條款牴觸保險法第54 條之1 之規定而無效','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-4301-017','110-4301',17,'single_choice','下列關於危險增加之敘述，依保險法之規定，何者正確？','危險增加，若係因要保人之行為所致者，如保險人知悉後仍繼續收受保險費，不影響保險人終止契 約之權利','危險增加，非由於要保人或被保險人之行為所致者，要保人或被保險人應於知悉後5 日內通知保 險人','危險增加，非由於要保人或被保險人之行為所致者，須達終止契約之程度，始負通知保險人之義務','危險增加，若係因防護保險人之利益者，即使該危險增加係因要保人之行為所導致，亦無需通知保 險人','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-4301-018','110-4301',18,'single_choice','甲購新車一輛，向A 保險公司投保汽車竊盜損失保險。投保後一星期該車遭竊，甲因急於出國，於 向警察局完成報案手續後，旋即出國，3 個月後返國，始通知保險公司，並申請理賠。下列敘述何者 正確？','因甲違反危險事故發生之通知義務，A 保險公司無須理賠','甲雖違反危險事故發生之通知義務，A 保險公司仍須理賠，但得對甲請求因遲延通知之損害賠償','因甲違反危險事故發生之通知義務，A 保險公司得解除契約','A 保險公司得解除契約，並請求損害賠償','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-4301-019','110-4301',19,'single_choice','下列關於保險代位之敘述，何者正確？','被保險人因保險人應負保險責任之損失發生，而對於第三人有損失賠償請求權者，保險人得於給付 賠償金額後，代位行使被保險人對第三人之請求權；其所得請求之內容與數額，以被保險人對第三 人得請求之內容與數額為限','保險人行使代位權時，不得對被保險人之配偶或未成年子女主張，但子女已成年者不在此限','保險人對第三人所得行使代位權之事由，不限於侵權行為損害賠償請求權','保險人不得對被保險人之家屬或受僱人行使代位權，但損失係由其故意或重大過失所引起者，不在 此限','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-4301-020','110-4301',20,'single_choice','甲進口較新之二手車，其價值新臺幣（下同）一百萬元，再以不實行照及新車照片，向A 保險公司 投保保險金額三百萬元之新車車體險。投保後不及2 個月，該車於高速公路行駛途中突然起火，全 車燒燬。警方事故資料除揭露該車真正出廠年份外，交通事故鑑定單位也確認本件為意外失火所致。 依保險法之規定，下列關於保險契約效力之敘述，何者正確？','本契約係因甲之詐欺而訂立，契約無效，保險公司無須理賠','本契約係因甲之詐欺而訂立之超額保險，保險公司行使契約解除權後，無須理賠','本件事故為意外所致，保險公司仍應就合理車價為理賠','本件事故之發生與虛報車價之間無因果關係，保險公司仍應就保險金額之全部為理賠','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-4301-021','110-4301',21,'single_choice','A 公司於民國（下同）105 年1 月向B 產物保險股份有限公司（下稱B 公司）投保公共意外責任險。 A 公司廠房於105 年5 月失火，火勢延燒造成C 公司廠房損失。C 公司於105 年10 月起訴A 公司， 於108 年10 月判決確定A 公司應賠償C 公司之損失。因A 公司失火後即不再營業，亦無資產可供 執行，C 公司乃於110 年9 月依保險法第94 條向B 公司提起訴訟，請求保險理賠。試問：C 公司對 B 公司之訴訟有無罹於時效？該時效應自何時起算？','依保險法第65 條，應自保險得為請求之日（105 年5 月失火）起算二年，因此已經罹於時效','依保險法第90 條被保險人受賠償之請求，亦即應自105 年10 月起算二年，因此已經罹於時效','應依被保險人侵權行為責任發生日起算二年，亦即應自105 年5 月失火起算二年，因此已經罹於 時效','應自被保險人對第三人應負損失賠償責任確定時起算，亦即應自108 年10 月起算二年，因此尚未 罹於時效','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-4301-022','110-4301',22,'single_choice','甲以自己為被保險人投保終身壽險，一年後因欠繳保險費，經保險人催告後仍未繳，契約停止效力。 甲在停效後六個月內，向保險人申請復效。下列有關復效規定之敘述，何者錯誤？','甲申請恢復效力時，保險人不得請求甲提供可保證明','除保險契約另有約定外，甲須至保險人之營業所交付欠繳之保險費、利息及其他費用','甲依法交付保險費、利息及其他費用後，保險契約即刻恢復效力','保險人不得拒絕甲之申請恢復契約效力','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-4301-023','110-4301',23,'single_choice','下列有關保險業對利害關係人放款之敘述，何者正確？','保險業對利害關係人之放款應有十足擔保','保險業對利害關係人放款之擔保以不動產為限','保險業不得對利害關係人放款','保險業對利害關係人之放款皆應經董事會特別決議通過','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-4301-024','110-4301',24,'single_choice','關於傷害保險契約之保險金給付，下列何種情況，保險人得不負保險責任？','被保險人處理漁貨不慎遭刺傷而感染海洋弧菌後死亡','被保險人手術期間，因醫生過失導致被保險人死亡','被保險人於接受新冠疫苗注射後，因發生嚴重副作用致死','被保險人於契約訂約二年後故意自殺','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-4301-025','110-4301',25,'single_choice','A 公司向B 產物保險股份有限公司（下稱B 公司）於投保工程保險後，因國際上發生重大事故，導 致B 公司安排再保險費超過原保險契約之保險費，下列敘述何者正確？','因國際發生重大事故導致危險增加，雖非因要保人或被保險人之行為所致，但B 公司仍得主張調 高保險費','因國際發生重大事故導致危險增加，非因要保人或被保險人之行為所致者，A 公司應於知悉後十日 內通知保險人。如A 公司違反通知義務時，B 公司僅得請求損害賠償','國際上發生重大事故導致再保險費提高，如B 公司欲請求增加保險費，應依實際狀況判斷有無情 事變更原則之適用','國際發生重大事故導致再保險費提高，B 公司僅得依保險法第60 條第1 項之規定向A 公司主張終 止契約','保險法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-026','110-4301',26,'single_choice','票據上之權利，因時效或手續之欠缺，而歸於消滅時，執票人對於發票人或承兌人，於其實質上所得 之利益之限度，仍得請求償還其利益，票據法第22 條第4 項定有明文。甲簽發即期支票，執票人乙 之利益償還請求權之消滅時效期間，依最高法院見解，下列之計算方法，何者正確？','乙僅得自退票日起算3 年內向甲請求','乙僅得自發票日起算3 年內向甲請求','乙得自退票日起算15 年內向甲請求','乙得自支票時效完成後15 年內向甲請求','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-027','110-4301',27,'single_choice','甲因向乙借款，簽發無記名支票一紙作為擔保，但因其信用不良，故乙要求丙出面保證甲之債務，丙 隨即在該支票背面簽名。下列敘述何者正確？','丙應負票據背書人之責任','丙應負票據保證人之責任','丙應負票據背書人及保證人之責任','丙不負任何票據責任','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-028','110-4301',28,'single_choice','甲簽發匯票一張，金額新臺幣（下同）10 萬元予受款人乙，指定付款人為A。乙又將該票據背書轉 讓予丙，丙經乙同意後將該票據金額變造為20 萬元，其後空白背書轉讓予丁，丁又再將票據交付轉 讓予戊。下列敘述何者正確？','甲為發票人，就該票據負最終責任，為20 萬元','乙背書時之票據金額為10 萬元，所應負之票據責任為10 萬元','丁轉讓該票據時，票據金額為20 萬元，丁之票據責任為20 萬元','戊若行使追索權，得向丙請求20 萬元','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-029','110-4301',29,'single_choice','甲簽發一張面額新臺幣（下同）50 萬元之匯票交與受款人乙，在到期日之前該匯票被丙盜取，丙偽 刻乙之印章而偽造乙之背書後，將該匯票以50 萬元之代價讓與丁，丁如不獲付款時，下列敘述何者 正確？','甲無須對丁負責','因被背書人丁以相當之對價善意取得該票據，甲仍須負票據責任','丙非票據之權利人，其偽造之背書不生效力，甲無須負票據責任','乙之印章蓋在票據上，故須負票據責任','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-030','110-4301',30,'single_choice','甲持有匯票一紙，到期日為民國（下同）102 年6 月5 日，甲最遲應於下列何日期向付款人提示請求 付款，始得保有對前手之追索權？','102 年6 月6 日','102 年6 月7 日','102 年6 月8 日','102 年6 月9 日','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-031','110-4301',31,'single_choice','甲簽發發票日為民國101 年7 月1 日，面額新臺幣10 萬元之支票一張交付受款人乙，乙背書交付 丙，丙背書交付丁，丁塗銷乙之背書後將支票背書交付戊。如戊依票據法之規定向付款銀行遵期為付 款提示被拒絕、取得退票理由單後對乙、丙、丁追索，並於民國102 年6 月30 日請求甲付款。下列 敘述何者正確？','甲與乙均應負票據責任','丙與丁均應負票據責任','甲與丁均應負票據責任','甲、乙、丙、丁均應負票據責任','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('110-4301-032','110-4301',32,'single_choice','甲於民國（下同）109 年5 月1 日簽發以同日為發票日之記名支票予乙，發票地與付款地均在臺北 市，乙於翌日背書轉讓予丙，丙於同年5 月10 日提示付款，遭付款人退票拒付，之後丙未有其他作 為，而於同年5 月15 日向甲、乙行使追索權，對於追索權行使，下列敘述何者錯誤？','丙喪失對乙之追索權','丙未喪失對甲之追索權','丙行使追索權時，縱無約定，亦得請求自發票日起之利息','丙行使追索權時，得請求追索之必要費用','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-033','110-4301',33,'single_choice','住所設於臺北市之甲於民國109 年12 月1 日簽發以同日為發票日之記名支票一紙，交付予住所地設 於高雄市之乙，付款地為臺南市，付款人為A 銀行，金額為新臺幣100 萬元整，甲匆忙間漏未記載 發票地，該支票之發票地為何？','臺北市','高雄市','臺南市','未記載發票地，該支票無效','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-034','110-4301',34,'single_choice','甲簽發一張支票與乙，並由付款銀行A 保付，乙之後將本張支票背書轉讓與丙。下列敘述何者正確？','本張支票僅由A 負票據責任','本張支票僅由A、甲負票據責任','本張支票由A、甲、乙負票據責任','丙應遵守法定提示期間，方得行使票據權利','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-035','110-4301',35,'single_choice','甲簽發支票一紙交付受款人乙，其後乙於票據背面記載「禁止背書轉讓」並於其旁簽名，背書交付給 丙，丙再背書轉讓給丁。丁依法定付款提示期限向付款銀行提示不獲付款，丁行使追索權時，下列敘 述何者正確？','丁可向甲、乙、丙行使追索權','丁可向甲、乙行使追索權','丁可向甲、丙行使追索權','丁僅可向甲行使追索權','票據法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-036','110-4301',36,'single_choice','近日國際股市異常波動，連帶使得業績甚佳的A 上市公司（下稱A 公司）的股價亦逐步下跌。A 公 司想要藉由庫藏股的實施，買回公司股份，進而維持公司信用。下列對於此一作法可行性的說明，何 者正確？','可行，但應先經過董事會的特別決議，並於最近一次之股東會報告','可行，但其買回股份之數量比例不得超過A 公司已發行股份總數3%','不可行，除非庫藏股實施的目的改為「為轉讓股份予員工而買回股份」','不可行，因基於此一目的所為股份之買回，屬於證券交易法所禁止的連續交易行為','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-037','110-4301',37,'single_choice','A 上市公司依章程規定設有五名獨立董事，並設置審計委員會。其中一名獨立董事甲於任期中因健 康因素請辭，在A 上市公司尚未補選獨立董事前，若其擬就委任簽證會計師事項為決定者，下列敘 述何者正確？','應直接經由全體董事三分之二以上同意之決議為之','應先經審計委員會至少三名獨立董事之同意後，再經董事會決議為之','得先經審計委員會至少二名獨立董事之同意後，再經董事會決議為之','得直接經由全體獨立董事三分之二以上同意之決議為之','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-038','110-4301',38,'single_choice','A 公司為一家從事主機板製造的上櫃公司，該公司設有甲、乙、丙3 名獨立董事。近期，甲、乙、丙 3 人同時辭去獨立董事之職務，則A 公司依法應自事實發生之日起至遲幾日內，召開股東臨時會補 選之？','30 日','50 日','60 日','90 日','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-039','110-4301',39,'single_choice','A 公司為一家公開發行股票之公司，該公司設有五名董事。最近，A 公司召開股東會改選董事及監察 人。依證券交易法之規定及司法實務見解，下列敘述何者錯誤？','具控制與從屬關係之B 公司與C 公司皆為A 公司之法人股東，除經主管機關核准者外，不得由B 公司之代表人當選A 公司之董事且C 公司之代表人當選A 公司之監察人','A 公司除經主管機關核准者外，監察人間應至少一席以上，不得具有配偶或二親等以內之親屬關係','A 公司之董事間皆不得具有配偶或二親等以內之親屬關係','A 公司監察人與董事間皆為二親等以內親屬，則監察人中所得選票代表選舉權較低者，其當選失 其效力','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],6,6,'parsed','pending_manual_review',null,true),
('110-4301-040','110-4301',40,'single_choice','A 上櫃公司（下稱A 公司）擬於6 月15 日召開本年度股東常會，本次會議並將選舉董事。截至本次 股東會之股票停止過戶日，法人股東B 持有A 公司普通股之表決權數已達A 公司已發行股份總表決 權數之3.3%，下列敘述何者正確？','A 公司得委由主管機關核准之股務代理機構，擔任A 公司股東之受託代理人，代理股東出席本次 股東會','只要是A 公司之股東，均可委託信託事業擔任A 公司股東委託書之徵求人','股東B 得以自行書寫之委託書取代A 公司印發之委託書用紙，委託他人代理出席，並行使表決權','自然人甲得僅受股東B 一人之委託，代理股東B 出席本次股東會，行使B 全部之表決權','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('110-4301-041','110-4301',41,'single_choice','A 公司已持有B 上櫃公司（下稱B 公司）有表決權股份超過50%，今A 公司計畫繼續加碼買進B 公 司股份達到90%，之後即可與B 公司進行簡易合併，若A 公司不想在櫃檯買賣市場慢慢買進B 公司 股票，而擬以公開收購方式為之，則對A 公司擬進行之公開收購，下列敘述何者正確？','A 公司應向主管機關提出具有履行支付收購對價能力之證明後，始得為之','A 公司不須向證券主管機關申報，即得為之','A 公司不得採用公開收購方式來買進B 公司股票','A 公司身為B 公司之控制股東，則其未取得B 公司股東會同意之前，不得採用公開收購方式來買 進B 公司股票','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('110-4301-042','110-4301',42,'single_choice','A 上市食品公司決定私募新股，下列敘述何者正確？','須經公司股東會已發行股份總數過半數股東之出席，出席股東表決權三分之二以上之同意，始得為之','不限於向金融機構私募，但均有應募人數限制','應依證券交易法第22 條規定申報生效後為之','依法決議後，可於2 年內分次辦理','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('110-4301-043','110-4301',43,'single_choice','甲是剛踏入社會的新鮮人，想將部分積蓄拿來投資上市有價證券，下列有關國內證券市場相關法制 之敘述何者錯誤？','政府發行之債券，其上市由主管機關以命令行之，不適用證券交易法有關上市之規定','上市有價證券之買賣，應於證券交易所開設之有價證券集中交易市場為之。但基於法律規定所生之 效力，不能經由有價證券集中交易市場之買賣而取得或喪失證券所有權者，不在此限','上市有價證券之買賣，應於證券交易所開設之有價證券集中交易市場為之。但政府所發行債券之買 賣，不在此限','上市有價證券之買賣，應於證券交易所開設之有價證券集中交易市場為之。但私人間之直接讓受， 其數量不超過該證券1 個成交單位，且前後兩次之讓受行為相隔不少於6 個月者，不在此限','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('110-4301-044','110-4301',44,'single_choice','X 公司是一家上市電子公司，今X 公司欲透過發行有價證券之方式，籌措公司所需之資金，故與Y 證券公司簽訂有價證券承銷契約。契約中載明於承銷期間屆滿後，對於約定承銷之有價證券，若未能 全數銷售者，其賸餘數額之有價證券，應由Y 證券公司自行認購之。依證券交易法之規定，此種有 價證券承銷方式稱為：','包銷','直銷','代銷','分銷','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('110-4301-045','110-4301',45,'single_choice','A 上櫃公司（下稱A 公司）董事長甲於取得A 公司股票後6 個月內再行賣出，因而獲得利益共計新 臺幣（下同）150 萬元，依證券交易法之規定，下列敘述何者正確？','A 公司應請求甲將該150 萬元利益歸於公司，無須經股東會決議','主管機關得處甲24 萬元以上480 萬元以下之罰鍰','甲短線交易之獲利行為已構成證券交易法上之刑事犯罪','A 公司非上市公司，故甲無須負任何責任','證券交易法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],7,7,'parsed','pending_manual_review',null,true),
('110-4301-046','110-4301',46,'single_choice','甲在X 法院起訴請求乙給付新臺幣（下同）800 萬元，獲勝訴判決並宣告供擔保後得假執行。乙提起 上訴；甲依假執行判決供擔保，就乙在X 法院轄區之丙銀行A 存款（50 萬元）及在Y 法院轄區之B 房地（價值700 萬元）聲請強制執行。下列敘述，何者正確？','甲向X 法院聲請執行乙之A 存款及B 房地時，X 法院就A 存款得扣押、換價，就B 房地得查封、 拍賣','甲向Y 法院聲請執行乙之A 存款及B 房地時，Y 法院就B 房地得查封、拍賣，就A 存款應囑託 X 法院扣押、換價','判決確定前，執行法院就A 存款及B 房地僅得實施扣押及換價。換價後應提存案款','判決確定前，執行法院僅得扣押A 存款及查封B 房地，不能實施換價','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('110-4301-047','110-4301',47,'single_choice','甲以命乙給付金錢之確定判決為執行名義，主張未辦保存登記之A 屋為乙所有，聲請執行法院對該 屋強制執行，但未提出A 屋之產權證明。經執行法院查封A 屋後，丙提出買賣契約及匯款證明，主 張丙於甲聲請強制執行前已取得A 屋之事實上處分權。執行法院續為下列處置，何者正確？','命甲10 日內陳報乙之其他財產，如逾期即駁回強制執行之聲請','諭知甲，經其同意後，撤銷對A 屋之查封','依職權延緩執行，等待丙提第三人異議之訴釐清A 屋權利歸屬','通知乙、丙到場對質，並命甲、乙辯論，調查A 屋權利歸屬後，據以處置','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('110-4301-048','110-4301',48,'single_choice','執行法院拍賣已查封之A 車時，已預定拍賣之底價為新臺幣（下同）50 萬元。下列敘述，何者錯誤？','應買人出價為49 萬元時，應不予拍定','未拍定時，得依50 萬元作價由執行債權人承受','拍賣無人應買，執行債權人亦不願承受時，應撤銷該動產之查封','未拍定，執行債權人亦不願承受時，應撤銷該動產之拍賣','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('110-4301-049','110-4301',49,'single_choice','債務人乙以其所有之A 地為債權人甲設定抵押權後，將該地出租予第三人丙。嗣甲執拍賣抵押物A 地之裁定為執行名義，聲請強制執行。執行法院以「A 地現由丙占有使用，拍定後不點交」之拍賣條 件進行拍賣，由丁拍定。丁在繳納尾款前，以其取得內容記載乙、丙坦承上開租賃關係確為通謀虛偽 之切結書為由，主張前揭拍賣條件應變更為「拍定後點交」，向執行法院聲明異議。假設上開切結書 內容為真正，下列敘述，何者正確？','上開拍賣程序業因拍定而終結，丁聲明異議為不合法，應駁回其異議','執行法院應撤銷原先之拍定，重為拍賣','執行法院應依丁之異議，更正上開拍賣條件，並將A 地點交予丁','A 地既以「拍定後不點交」為拍賣條件，丁於拍定後即不得再為相反主張，執行法院應駁回其異議','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('110-4301-050','110-4301',50,'single_choice','關於金錢請求權之強制執行所應適用（準用）之程序，下列敘述，何者錯誤？','債權人甲聲請執行債務人乙所有之A 股份有限公司實體股票，應依對於動產之執行程序辦理','債權人甲聲請執行債務人乙於A 有限公司之出資，應準用債務人對於第三人之金錢債權執行程序 辦理','債權人甲聲請執行債務人乙航空公司之飛機（屬民用航空法所定航空器），應準用動產之執行程序 辦理','債權人甲聲請執行債務人乙之礦業權，應準用不動產之執行程序辦理','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('110-4301-051','110-4301',51,'single_choice','甲執命乙給付甲新臺幣1,500 萬元本息之確定判決為執行名義，聲請就乙所有之A 耕地及其上農舍 為強制執行，下列何者非執行法院得實施之執行方法？','以投標之方法拍賣','命令讓與','強制管理','拍賣併強制管理','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],8,8,'parsed','pending_manual_review',null,true),
('110-4301-052','110-4301',52,'single_choice','關於探視子女之強制執行事件，執行名義內容為「債權人甲於每月第一週、第三週週五下午5 時起 至週日下午5 時止，得親自或委託親人前往子女丙所在處所接丙外出，並由甲照顧至週日下午5 時」。 若債務人乙於上開履行期屆至時，將丙安置於丁經營之民間托育設施內。下列敘述，何者正確？','丁係乙之使用人，為上開執行名義之效力所及，執行法院應依甲之聲請逕對丁為強制執行','探視子女事件係屬不可代替行為請求權之執行，執行法院得通知有關機關為適當之協助，是丁有配 合義務','若丁拒絕配合執行，執行法院應退出丁經營之民間托育設施，不得繼續執行','丁並非執行名義效力所及之人，且乙已將丙安置在丁處所，甲僅能另行對丁取得執行名義，執行法 院應駁回甲之強制執行聲請','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('110-4301-053','110-4301',53,'single_choice','就下列事項所取得之確定判決，何者須向法院聲請強制執行始得實現權利？','命債務人乙將A 地所有權移轉登記予債權人甲','命債務人乙就A 地以價金新臺幣350 萬元之同一條件與債權人甲訂立買賣契約','命債務人乙在某報刊登啟事向債權人甲道歉','命債務人乙協同債權人甲向監理機關辦理B 車過戶登記','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('110-4301-054','110-4301',54,'single_choice','債務人乙所有之財產，已經金錢債權人甲聲請為終局執行中，乙之另一債權人丙對同一財產復聲請 假扣押執行。下列敘述，何者正確？','基於甲終局執行之優先性，即不應再准許丙之假扣押執行','因於甲終局執行終結前，甲仍有可能撤回執行，故應附條件准許丙於甲撤回執行時，得為假扣押執行','基於平等主義之原則，仍應准許丙之假扣押執行，同受清償分配','應視丙之假扣押執行為參與分配，以其應受分配金額予以提存','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
('110-4301-055','110-4301',55,'single_choice','債權人甲持假扣押裁定為執行名義，聲請強制執行債務人乙所有未辦保存登記之A 建物，經執行法 院實施查封後，債權人丙復持命乙拆除A 建物返還其基地之確定判決為執行名義，聲請強制執行， 執行法院應否准許丙之聲請？','不應准許，因先後執行程序不得並存，應以執行時間之先後定其優劣','不應准許，因先後執行程序發生競合，後執行應於排除前執行效果後始得執行','應予准許，因保全執行之效力，並未排除法院之強制執行','應予准許，因先後執行債權人所執行之權利不同','強制執行法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],9,9,'parsed','pending_manual_review',null,true),
